import{_ as t,o as e,c as o,a5 as r}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"变彩（游彩）","description":"","frontmatter":{"title":"变彩（游彩）","phenomenon":"play-of-color"},"headers":[],"relativePath":"zh/classification/optical-phenomena/play-of-color.md","filePath":"zh/classification/optical-phenomena/play-of-color.md","lastUpdated":1789241305000}'),l={name:"zh/classification/optical-phenomena/play-of-color.md"};function d(i,a,n,s,h,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="变彩-游彩" tabindex="-1">变彩（游彩） <a class="header-anchor" href="#变彩-游彩" aria-label="Permalink to &quot;变彩（游彩）&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>变彩是欧泊最具代表性的视觉现象。白光进入欧泊内部由规则排列的二氧化硅小球形成的微结构时， 不同波长的光会发生衍射与干涉；当观察角度改变，呈现跳动、游移的光谱色斑。变彩的强弱、颜色范围 与分布受微结构有序程度、体色、切磨方式和观察光线共同影响。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>微结构衍射与干涉：欧泊中规则排列的二氧化硅小球及其间隙形成周期性结构。白光进入后，不同波长 沿不同方向增强或减弱，因此观察方向变化时会连续看到不同的色彩组合。这里的“游彩”描述的是视觉 表现，不等同于普通的体色或单一光源下的闪光。</p><h2 id="示例宝石" tabindex="-1">示例宝石 <a class="header-anchor" href="#示例宝石" aria-label="Permalink to &quot;示例宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>微结构</th><th>色彩表现</th></tr></thead><tbody><tr><td>Precious Opal / 贵欧泊</td><td>ordered silica-sphere domains</td><td>angular spectral flashes</td></tr><tr><td>Black Opal / 黑欧泊</td><td>dark body tone + silica-sphere domains</td><td>red, green, blue</td></tr><tr><td>White Opal / 白欧泊</td><td>silica-sphere domains</td><td>green, blue, orange</td></tr></tbody></table><p><em>详见<a href="./intro.html">光学现象总览</a>。</em></p>',8)])])}const f=t(l,[["render",d]]);export{m as __pageData,f as default};
